using System.Windows; using System.Windows.Input; using System.Windows.Controls; using Forms=System.Windows.Forms;
namespace ChichiCapture;
public partial class RegionWindow:Window{Point start;public Rect Selection{get;private set;}public RegionWindow(){InitializeComponent();var v=Forms.SystemInformation.VirtualScreen;Left=v.Left;Top=v.Top;Width=v.Width;Height=v.Height;}void Window_Down(object s,MouseButtonEventArgs e){start=e.GetPosition(this);Box.Visibility=Visibility.Visible;CaptureMouse();}void Window_Move(object s,MouseEventArgs e){if(e.LeftButton!=MouseButtonState.Pressed)return;var p=e.GetPosition(this);Canvas.SetLeft(Box,Math.Min(start.X,p.X));Canvas.SetTop(Box,Math.Min(start.Y,p.Y));Box.Width=Math.Abs(p.X-start.X);Box.Height=Math.Abs(p.Y-start.Y);}void Window_Up(object s,MouseButtonEventArgs e){var p=e.GetPosition(this);Selection=new Rect(Left+Math.Min(start.X,p.X),Top+Math.Min(start.Y,p.Y),Math.Abs(p.X-start.X),Math.Abs(p.Y-start.Y));ReleaseMouseCapture();DialogResult=Selection.Width>1&&Selection.Height>1;}void Window_KeyDown(object s,KeyEventArgs e){if(e.Key==Key.Escape){DialogResult=false;Close();}}}
